window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0de9f46b40d3ca12"]={"versions": [{"id": "FIG-0de9f46b40d3ca12", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Interaktions- und Datenflussdiagramm im Kontext der AUTOSAR Classic Diagnostic Stack-Architektur. Das Diagramm illustriert die Abwicklung des UDS-Dienstes 0x19 (ReadDTCInformation) mit Subfunktion 0x05 (reportDTCSnapshotRecordByRecordNumber) zwischen externem Diagnosetester, Diagnostic Communication Manager (DCM) und Diagnostic Event Manager (DEM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>External Tester</strong>: Externes Diagnosewerkzeug, sendet UDS-Anfragen und empfängt UDS-Antworten.\n</li><li><strong>DCM (Diagnostic Communication Manager)</strong>: Protokollhandler für Diagnoseanfragen auf Service-Ebene.\n</li><li><strong>DEM (Diagnostic Event Manager)</strong>: Diagnosespeicher-Modul inklusive <code>Event memory</code> mit Tabellenstruktur für DTCs (<code>DTC1</code>, <code>DTC2</code>, <code>free</code>) und zugeordnete Freeze-Frame-Datensätze (<code>FreezeFrame (1st set)</code>, <code>FreezeFrame (2nd set)</code>).\n</li><li><strong>Schnittstellen DCM &lt;-&gt; DEM</strong>:\n<ul class=\"fig-list\"><li><code>Dem_GetDTCOfFreezeFrameRecord</code>: Funktionsaufruf zur Ermittlung des DTC anhand der Snapshot-Record-Nummer; Rückgabe: <code>DTC</code>.\n</li><li><code>Dem_GetFreezeFrameDataIdentifiersByDTC</code>: Abfrage der Datenidentifikatoren (DIDs) für den DTC; Rückgabe: <code>List of DataIDs</code>.\n</li><li><code>Dem_DisableDTCRecordUpdate</code>: Sperren der Aktualisierung des Snapshot-Datensatzes im DEM.\n</li><li><code>Dem_GetFreezeFrameDataByDTC</code>: Auslesen der Datensatzinhalte; Rückgabe: <code>Snapshot record(s)</code>.\n</li><li><code>Dem_EnableDTCRecordUpdate</code>: Freigabe der Datensatz-Aktualisierung im DEM.\n</li></ul>\n</li><li><strong>UDS-Nachrichten</strong>:\n<ul class=\"fig-list\"><li>Request: <code>$19 $05 (RecordNumber)</code>\n</li><li>Response: <code>$59 $05 (DTC + DTCStatus + RecordNumber + Number of Identifiers + SnapshotData)</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der External Tester sendet die Diagnoseanfrage <code>Request: $19 $05 (RecordNumber)</code> an den DCM.\n</li><li>Der DCM ruft <code>Dem_GetDTCOfFreezeFrameRecord</code> am DEM auf und erhält den zugehörigen <code>DTC</code> zurück.\n</li><li>Der DCM fragt über <code>Dem_GetFreezeFrameDataIdentifiersByDTC</code> die DIDs ab und empfängt <code>List of DataIDs</code>.\n</li><li>Der DCM sperrt die Aktualisierung des Datensatzes via <code>Dem_DisableDTCRecordUpdate</code>.\n</li><li>Der DCM liest die Rohdaten mittels <code>Dem_GetFreezeFrameDataByDTC</code> aus und erhält <code>Snapshot record(s)</code>.\n</li><li>Der DCM gibt die Aktualisierung über <code>Dem_EnableDTCRecordUpdate</code> wieder frei.\n</li><li>Der DCM assembliert und übermittelt die UDS-Antwort <code>Response: $59 $05 (DTC + DTCStatus + RecordNumber + Number of Identifiers + SnapshotData)</code> an den External Tester.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RecordNumbering</strong>: Die Snapshot-Record-Nummern müssen absolut adressiert sein (<code>RecordNumbers must be absolute</code>).\n</li><li><strong>Konsistenzsicherung</strong>: Das Umschließen des Lesezugriffs (<code>Dem_GetFreezeFrameDataByDTC</code>) mit <code>Dem_DisableDTCRecordUpdate</code> und <code>Dem_EnableDTCRecordUpdate</code> stellt Datenkonsistenz sicher und verhindert Überschreibungen während des Auslesevorgangs.\n</li><li><strong>Fehlerbehandlung</strong>: Die Sequenz zeigt den Gutfall; bei nicht vorhandenen Record-Nummern oder ungültigen Parametern greifen entsprechende negative Response-Codes (NRCs) bzw. Fehler-Rückgabewerte der DEM-APIs.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cd8a5e0cf7d63e09", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Interaktions- und Datenflussdiagramm im Kontext der AUTOSAR Classic Diagnostic Stack-Architektur. Das Diagramm zeigt das strukturelle Rahmenwerk für den UDS-Service 0x19 0x05 (Report DTC Snapshot Record By Snapshot Record Number) mit Interaktionspfeilen zwischen drei unbeschrifteten Entitätsblöcken (Tester, Server-DCM, Diagnosespeicher DEM) sowie einer tabellarischen Speicherstruktur. Sämtliche Beschriftungen der Blöcke, Schnittstellenfunktionen und Payloads fehlen im Diagramminhalt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Drei unbeschriftete Hauptblöcke</strong>: Entsprechen strukturell einem externen Tester, einem Diagnosekommunikationsmanager und einem Diagnosespeicher.\n</li><li><strong>Speicherstruktur</strong>: Matrix mit 3 Spalten und 3 Zeilen zur Repräsentation von Ereignisspeichereinträgen (ohne Textbeschriftung).\n</li><li><strong>Schnittstellen</strong>:\n<ul class=\"fig-list\"><li>Zwei vertikale Pfeile für UDS-Request und UDS-Response zwischen oberem und linkem Block.\n</li><li>Fünf horizontale Funktionsaufruf-Pfeile vom linken Block zum rechten Block.\n</li><li>Drei horizontale Rückgabewert-Pfeile (rot) vom rechten Block zum linken Block.\n</li><li>Sämtliche API-Namen, Parameter und Nachrichteninhalte sind im Diagramm nicht beschriftet.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Diagnoseanfrage wird vom oberen Block an den linken Block übertragen.\n</li><li>Der linke Block führt sequenziell Funktionsaufrufe an den rechten Block aus:\n<ul class=\"fig-list\"><li>Erster Aufruf mit synchronem Rückgabewert.\n</li><li>Zweiter Aufruf mit synchronem Rückgabewert.\n</li><li>Dritter Aufruf (ohne Rückgabewertpfeil).\n</li><li>Vierter Aufruf mit synchronem Rückgabewert.\n</li><li>Fünfter Aufruf (ohne Rückgabewertpfeil).\n</li></ul>\n</li><li>Diagnoseantwort wird vom linken Block an den oberen Block zurückgesendet.\n</li><li>Alle konkreten Funktions- und Payload-Bezeichner sind unbeschriftet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Durch das vollständige Fehlen der textuellen Annotationen an den Funktions- und Nachrichtenpfeilen liefert das Diagramm für sich allein keine spezifizierten API-Namen, UDS-Payloadstrukturen oder Randbedingungen (wie Adressierungsregeln für Record-Nummern).\n</li><li>Das Sequenzmuster verdeutlicht auf rein grafischer Ebene eine 5-stufige Interaktion mit Absicherung/Klammerung (Aufrufe 3 und 5 ohne Rückgabepfeil um Aufruf 4) zur Konsistenzwahrung vor der abschließenden Antwortübermittlung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0de9f46b40d3ca12", "to": "FIG-cd8a5e0cf7d63e09", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Sämtliche Textbeschriftungen innerhalb der Komponentenblöcke (&quot;External Tester&quot;, &quot;DCM&quot;, &quot;DEM&quot;, &quot;Event memory&quot;, Tabelleninhalte DTC1/DTC2/free), an den Schnittstellenpfeilen (UDS-Request/Response, C-APIs Dem_GetDTCOfFreezeFrameRecord, Dem_GetFreezeFrameDataIdentifiersByDTC, Dem_DisableDTCRecordUpdate, Dem_GetFreezeFrameDataByDTC, Dem_EnableDTCRecordUpdate, Rückgabewerte) sowie Legende (&quot;Function call&quot;, &quot;Return value(s)&quot;) und Fußnote (&quot;RecordNumbers must be absolute&quot;) fehlen in der Darstellung (Rendering-/Exportfehler des Text-Layers).\n</li></ul>"}]};
